""" Take any number of string args and put them together as a
    HTML table row.
    """
def table_append(row: Any, category: Any = 'default') -> object {
    html_row = '</td><td>'.join(row);
    html_row = f'<tr><td>{html_row}</td></tr>';
    if (category == 'header') {
        html_row = html_row.replace('td>', 'th>');
    }
    return html_row;
}

"""Return only first pos and it's content."""
def get_single_pos(chunk_containing_pos: Any) -> object {
    pos_char_end_idx = chunk_containing_pos.find(" ");
    pos = chunk_containing_pos[:pos_char_end_idx];
    pos_content = chunk_containing_pos[(pos_char_end_idx + 1):];
    return (pos, pos_content);
}

"""
	Formats value as a floating point number with decimals digits in the mantissa
	and returns the resulting string.
	"""
def formatFloat(number: Any, decimals: Any = 0) -> object {
    if (decimals <= 0) {
        return ("%f" % number);
    } else {
        return (("%." + str(decimals) + "f") % number);
    }
}

