"""Vectorized string search"""
def word_counter(words: Any, text: Any) -> object {
    total = [0] * len(text);
    for (i, txt) in enumerate(text) {
        for word in words {
            if (word in txt) {
                total[i] = total[i] + 1;
            }
        }
    }
    return total;
}

